import React, { useState } from 'react';
import { useAuthStore } from '../store/authStore';
import { authAPI } from '../utils/api';

const LoginPage: React.FC = () => {
  const [email, setEmail] = useState('');
  const [code, setCode] = useState('');
  const [step, setStep] = useState<'email' | 'code'>('email');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const setAuth = useAuthStore((state) => state.setAuth);

  const handleSendCode = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!email) {
      setError('Email adresi gerekli');
      return;
    }

    setLoading(true);
    setError('');
    
    try {
      const response = await authAPI.sendLoginCode(email);
      setStep('code');
      console.log('✅ Kod gönderildi:', response.data.message);
    } catch (err: any) {
      console.error('❌ Kod gönderme hatası:', err);
      setError(err.response?.data?.error || 'Kod gönderilemedi');
    }
    setLoading(false);
  };

  const handleVerifyCode = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!code || code.length !== 6) {
      setError('6 haneli kodu girin');
      return;
    }

    setLoading(true);
    setError('');
    
    try {
      const response = await authAPI.verifyCode(email, code);
      console.log('✅ Giriş başarılı:', response.data);
      
      setAuth(response.data.token, response.data.userId, response.data.familyId);
      
      // Redirect to dashboard
      window.location.href = '/';
    } catch (err: any) {
      console.error('❌ Kod doğrulama hatası:', err);
      setError(err.response?.data?.error || 'Kod doğrulanamadı');
      setCode('');
    }
    setLoading(false);
  };

  const handleCodeChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const value = e.target.value.replace(/\D/g, '').slice(0, 6);
    setCode(value);
  };

  return (
    <div style={styles.container}>
      <div style={styles.card}>
        <div style={styles.header}>
          <h1 style={styles.title}>🏠 Aile Takip Sistemi</h1>
          <p style={styles.subtitle}>
            {step === 'email' ? 'Email adresinizi girin' : 'Doğrulama kodunu girin'}
          </p>
        </div>

        {error && (
          <div style={styles.error}>
            <span>⚠️ {error}</span>
          </div>
        )}

        {step === 'email' ? (
          <form onSubmit={handleSendCode} style={styles.form}>
            <div style={styles.inputGroup}>
              <label style={styles.label}>📧 Email Adresiniz</label>
              <input
                type="email"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                style={styles.input}
                placeholder="ornek@email.com"
                required
                autoFocus
              />
            </div>
            
            <button type="submit" style={styles.button} disabled={loading}>
              {loading ? 'Kod Gönderiliyor...' : '📧 Giriş Kodu Gönder'}
            </button>
            
            <div style={styles.info}>
              <p>✨ Yeni kullanıcıysanız otomatik kayıt olacaksınız</p>
              <p>📱 Kod email adresinize gönderilecek</p>
            </div>
          </form>
        ) : (
          <form onSubmit={handleVerifyCode} style={styles.form}>
            <div style={styles.codeInfo}>
              <p><strong>{email}</strong> adresine kod gönderildi</p>
            </div>
            
            <div style={styles.inputGroup}>
              <label style={styles.label}>🔑 Doğrulama Kodu</label>
              <input
                type="text"
                value={code}
                onChange={handleCodeChange}
                style={styles.codeInput}
                placeholder="123456"
                maxLength={6}
                required
                autoFocus
              />
            </div>
            
            <button type="submit" style={styles.button} disabled={loading}>
              {loading ? 'Doğrulanıyor...' : '✅ Giriş Yap'}
            </button>
            
            <button 
              type="button" 
              style={styles.backButton}
              onClick={() => {
                setStep('email');
                setCode('');
                setError('');
              }}
            >
              ← Email Değiştir
            </button>
          </form>
        )}
      </div>
    </div>
  );
};

const styles = {
  container: {
    minHeight: '100vh',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
    padding: '20px',
    fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif',
  },
  card: {
    backgroundColor: '#fff',
    borderRadius: '20px',
    padding: '40px',
    width: '100%',
    maxWidth: '400px',
    boxShadow: '0 20px 40px rgba(0,0,0,0.1)',
    textAlign: 'center' as const,
  },
  header: {
    marginBottom: '32px',
  },
  title: {
    fontSize: '28px',
    fontWeight: '800',
    color: '#2c3e50',
    margin: '0 0 8px 0',
  },
  subtitle: {
    fontSize: '16px',
    color: '#6c757d',
    margin: 0,
  },
  error: {
    backgroundColor: '#f8d7da',
    color: '#721c24',
    padding: '12px 16px',
    borderRadius: '8px',
    marginBottom: '20px',
    fontSize: '14px',
  },
  form: {
    display: 'flex',
    flexDirection: 'column' as const,
    gap: '20px',
  },
  inputGroup: {
    textAlign: 'left' as const,
  },
  label: {
    display: 'block',
    fontSize: '14px',
    fontWeight: '600',
    color: '#495057',
    marginBottom: '8px',
  },
  input: {
    width: '100%',
    padding: '16px',
    border: '2px solid #e9ecef',
    borderRadius: '12px',
    fontSize: '16px',
    outline: 'none',
    transition: 'border-color 0.3s ease',
    boxSizing: 'border-box' as const,
  },
  codeInput: {
    width: '100%',
    padding: '16px',
    border: '2px solid #e9ecef',
    borderRadius: '12px',
    fontSize: '24px',
    textAlign: 'center' as const,
    letterSpacing: '8px',
    fontWeight: '600',
    outline: 'none',
    boxSizing: 'border-box' as const,
  },
  button: {
    backgroundColor: '#007bff',
    color: '#fff',
    border: 'none',
    borderRadius: '12px',
    padding: '16px 24px',
    fontSize: '16px',
    fontWeight: '600',
    cursor: 'pointer',
    transition: 'all 0.3s ease',
  },
  backButton: {
    backgroundColor: 'transparent',
    color: '#6c757d',
    border: 'none',
    padding: '12px',
    fontSize: '14px',
    cursor: 'pointer',
    textDecoration: 'underline',
  },
  codeInfo: {
    backgroundColor: '#e3f2fd',
    padding: '16px',
    borderRadius: '8px',
    fontSize: '14px',
    color: '#1976d2',
  },
  info: {
    backgroundColor: '#e8f5e8',
    padding: '16px',
    borderRadius: '8px',
    fontSize: '14px',
    color: '#2e7d32',
  },
};

export default LoginPage;
